export function getRosterHero(id: string): RosterHero | undefined {
  return LAUNCH_ROSTER.find(h => h.id === id);
}

export function getRosterByFamily(family: ClassFamily): RosterHero[] {
  return LAUNCH_ROSTER.filter(h => h.family === family);
}

export function getRosterByRarity(rarity: LaunchRarity): RosterHero[] {
  return LAUNCH_ROSTER.filter(h => h.rarityTier === rarity);
}

export function getEvolutionChain(heroId: string): RosterHero[] {
  const hero = getRosterHero(heroId);
  if (!hero) return [];
  const chain: RosterHero[] = [];
  let current: RosterHero | undefined = hero;
  while (current?.evolvedFrom) {
    const prev = getRosterHero(current.evolvedFrom);
    if (!prev) break;
    chain.unshift(prev);
    current = prev;
  }
  chain.push(hero);
  return chain;
}

export function getEvolutionPaths(heroId: string): RosterHero[][] {
  const hero = getRosterHero(heroId);
  if (!hero?.evolvedInto?.length) return [[hero ?? getRosterHero(heroId)!]];
  return hero.evolvedInto.map(nextId => {
    const next = getRosterHero(nextId);
    if (!next) return [];
    return [hero, next, ...getEvolutionPaths(nextId).flat()];
  });
}

export const ROSTER_COMMONS   = LAUNCH_ROSTER.filter(h => h.rarityTier === 'common');
export const ROSTER_UNCOMMONS = LAUNCH_ROSTER.filter(h => h.rarityTier === 'uncommon');
export const ROSTER_RARES     = LAUNCH_ROSTER.filter(h => h.rarityTier === 'rare');
export const ROSTER_EPICS     = LAUNCH_ROSTER.filter(h => h.rarityTier === 'epic');
